//! 🧪️ Original caller grants own output backing, byte copies, transfers and physical retirement.
use super::*;
use crate::test_oracle::{layout_export_fixture_caller,LAYOUT_EXPORT_FIXTURE_STOCK,LAYOUT_EXPORT_FIXTURE_TURN};
fn operation()->semio_framework_job::Operation{semio_framework_job::Operation::new(semio_framework_job::OperationId(1964),semio_framework_job::RevisionId(1),semio_framework_job::Generation(3),7)}
#[test]fn original_output_undergrants_leave_bytes_unchanged_and_close_all_physical_capacity(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let operation=operation();let mut caller=layout_export_fixture_caller(operation,operation.generation);let length=row["length"].as_u64().unwrap()as usize;let source:Vec<u8>=(0..length).map(|at|(at*row["multiplier"].as_u64().unwrap()as usize+row["offset"].as_u64().unwrap()as usize)as u8).collect();let mut output=ChunkRope::new();assert!(output.terminal_is_empty());for bytes in source.chunks(OUTPUT_BODY_BYTES){loop{let demand=output.prepare_demand(bytes.len()).unwrap();if output.has_room(bytes.len()){break;}let denied=RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..LAYOUT_EXPORT_FIXTURE_TURN};let before=(output.len,output.digest,output.allocated_bytes());let step=caller.turn(denied,|cx|{let step=output.prepare_one(bytes.len(),cx.retained_grant())?;cx.consume_retained(step.progress())?;Ok(step)}).unwrap();assert_eq!(step.progress(),Default::default());assert_eq!(before,(output.len,output.digest,output.allocated_bytes()));caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|{let step=output.prepare_one(bytes.len(),cx.retained_grant())?;cx.consume_retained(step.progress())?;Ok(step)}).unwrap();}let denied=RetainedCloneGrant{maximum_copy_bytes:bytes.len()-1,..LAYOUT_EXPORT_FIXTURE_TURN};let mut work=OutputWork::new(denied);assert!(output.append(bytes,&mut work).is_err());assert_eq!(work.receipt(),Default::default());caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|{let mut work=OutputWork::new(cx.retained_grant());output.append(bytes,&mut work).map_err(crate::Fault::from)?;cx.consume_retained(work.receipt())?;Ok(())}).unwrap();}let mut actual=Vec::new();for turn in 0..100000{let(chunk,done)=caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|{let(chunk,done,progress)=output.transfer_one(cx.retained_grant())?;cx.consume_retained(progress)?;Ok((chunk,done))}).unwrap();if let Some(chunk)=chunk{actual.extend_from_slice(&chunk);}if done{break;}assert!(turn<99999);}assert_eq!(actual,source);assert_eq!(actual,crate::decode_base64(row["base64"].as_str().unwrap()).unwrap());for turn in 0..100000{if output.terminal_is_empty(){break;}caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|{let step=output.close_one(cx.retained_grant())?;cx.consume_retained(step.progress())?;Ok(step)}).unwrap();assert!(turn<99999);}assert!(output.terminal_is_empty());caller.retire(LAYOUT_EXPORT_FIXTURE_STOCK);}}
#[test]fn live_formatted_output_posts_stack_and_destination_copies_without_temporary_heap_owners(){let operation=operation();let mut caller=layout_export_fixture_caller(operation,operation.generation);let mut output=ChunkRope::new();while !output.has_room(OUTPUT_BODY_BYTES){caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|{let step=output.prepare_one(OUTPUT_BODY_BYTES,cx.retained_grant())?;cx.consume_retained(step.progress())?;Ok(step)}).unwrap();}let before=(output.len,output.digest,output.allocated_bytes());for grant in [RetainedCloneGrant{maximum_items:1,..LAYOUT_EXPORT_FIXTURE_TURN},RetainedCloneGrant{maximum_copy_bytes:OUTPUT_BODY_BYTES+HEADER_BYTES-1,..LAYOUT_EXPORT_FIXTURE_TURN},RetainedCloneGrant{maximum_depth:0,..LAYOUT_EXPORT_FIXTURE_TURN}]{let mut work=OutputWork::new(grant);assert!(output.append_format(format_args!("{}",123),&mut work).is_err());assert_eq!(work.receipt(),Default::default());assert_eq!(before,(output.len,output.digest,output.allocated_bytes()));}caller.turn(LAYOUT_EXPORT_FIXTURE_TURN,|cx|{let mut work=OutputWork::new(cx.retained_grant());let(result,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||output.append_format(format_args!("{} {:08X} {:.6} {}",'😀',0x10ffff,0.125,false),&mut work));result.map_err(crate::Fault::from)?;assert_eq!(physical.requested_bytes,0);assert_eq!(physical.released_bytes,0);assert!(!physical.overflowed);assert_eq!(work.receipt().copied_bytes,output.len*2+HEADER_BYTES*2);assert_eq!(work.receipt().copied_items,2);cx.consume_retained(work.receipt())?;Ok(())}).unwrap();crate::close_output_fixture(&mut output,&mut caller);caller.retire(LAYOUT_EXPORT_FIXTURE_STOCK);}
